class Hysteresis(FunctionBlock):
    def step(self, inputs, parameters, dt):
        value = inputs["value"]
        lower = parameters["lower"]
        upper = parameters["upper"]
        initial = parameters["initial"]
        active_below = parameters["active_below"]

        if "state" not in self.state:
            self.state["state"] = initial

        current_state = self.state["state"]

        if active_below:
            if value < lower:
                new_state = True
            elif value > upper:
                new_state = False
            else:
                new_state = current_state
        else:
            if value > upper:
                new_state = True
            elif value < lower:
                new_state = False
            else:
                new_state = current_state

        self.state["state"] = new_state
        return new_state

class OnDelay(FunctionBlock):
    def step(self, inputs, parameters, dt):
        active = inputs.get("active")
        delay = parameters["delay"]
        prev_active = self.state.get("prev_active", False)
        elapsed = self.state.get("elapsed", 0.0)
        if active:
            if prev_active:
                elapsed = elapsed + dt
            else:
                elapsed = 0.0
            self.state["prev_active"] = True
            self.state["elapsed"] = elapsed
            return elapsed >= delay
        else:
            self.state["prev_active"] = False
            self.state["elapsed"] = 0.0
            return False

class RateLimiter(FunctionBlock):
    def step(self, inputs, parameters, dt):
        target = inputs["target"]
        rise_rate = parameters["rise_rate"]
        fall_rate = parameters["fall_rate"]
        initial = parameters["initial"]

        if "output" not in self.state:
            self.state["output"] = initial

        current = self.state["output"]

        if target > current:
            max_change = rise_rate * dt
            new_value = current + max_change
            if new_value > target:
                new_value = target
        else:
            max_change = fall_rate * dt
            new_value = current - max_change
            if new_value < target:
                new_value = target

        self.state["output"] = new_value
        return new_value

class ValidityGate(FunctionBlock):
    def step(self, inputs, parameters, dt):
        value = inputs.get("value")
        valid = inputs.get("valid")
        fallback = parameters["fallback"]
        if valid:
            return value
        else:
            return fallback

class Threshold(FunctionBlock):
    def step(self, inputs, parameters, dt):
        value = inputs.get("value")
        threshold = parameters["threshold"]
        active_below = parameters["active_below"]
        if active_below:
            return value < threshold
        else:
            return value > threshold

class JOIN(FunctionBlock):
    def step(self, inputs, parameters, dt):
        N = parameters.get("N", 0)
        A = inputs.get("A", False)
        B = inputs.get("B", False)
        C = inputs.get("C", False)
        D = inputs.get("D", False)
        count = 0
        if A == True:
            count = count + 1
        if B == True:
            count = count + 1
        if C == True:
            count = count + 1
        if D == True:
            count = count + 1
        if count == N:
            return True
        return False

